import { execFile } from 'node:child_process';
import { realpath } from 'node:fs/promises';
import { basename, join, resolve } from 'node:path';
import { promisify } from 'node:util';
import { canonicalizePotentialPath, pathExists, safePackageName } from './fs.js';
import { assertOwnedGitCache, prepareOwnedGitCache } from './git-cache.js';
const execFileAsync = promisify(execFile);
export async function prepareRepoSource(input, workRoot, options = {}) {
    if (options.ref !== undefined)
        validateGitRef(options.ref);
    const trimmed = input.trim();
    if (!trimmed)
        throw new Error('repo input is required');
    if (await pathExists(trimmed)) {
        const repoRoot = await realpath(resolve(trimmed));
        const gitTopLevel = await gitOutput(repoRoot, ['rev-parse', '--show-toplevel']);
        const isRepoRoot = gitTopLevel !== null && resolve(gitTopLevel) === repoRoot;
        const commit = isRepoRoot ? await gitOutput(repoRoot, ['rev-parse', 'HEAD']) : null;
        const branch = isRepoRoot ? await gitOutput(repoRoot, ['branch', '--show-current']) : null;
        if (options.ref !== undefined) {
            const requestedCommit = await gitOutput(repoRoot, ['rev-parse', '--verify', `${options.ref}^{commit}`]);
            if (!isRepoRoot || !commit || !requestedCommit || requestedCommit !== commit) {
                throw new Error(`Local source ref must resolve to the current HEAD: ${options.ref}`);
            }
        }
        const remote = isRepoRoot ? await gitOutput(repoRoot, ['remote', 'get-url', 'origin']) : null;
        const status = isRepoRoot
            ? await gitOutput(repoRoot, ['status', '--porcelain', '--untracked-files=all'])
            : null;
        return {
            repoRoot,
            sourceUrl: remote || `local:${basename(repoRoot)}`,
            repoSlug: basename(repoRoot),
            sourceKind: 'local',
            sourceCommit: commit,
            sourceRef: options.ref ?? branch,
            sourceDirty: isRepoRoot ? status !== null : null,
        };
    }
    const url = toGitHubUrl(trimmed);
    const repoSlug = url.replace(/^https:\/\/github\.com\//, '').replace(/\.git$/, '');
    const boundaryRoot = await canonicalizePotentialPath(workRoot);
    const cloneRoot = join(boundaryRoot, '.repo-source-cache', safePackageName(repoSlug));
    const target = join(cloneRoot, 'repo');
    const snapshot = await refreshGitCheckout({ url, target, boundaryRoot, ref: options.ref });
    return {
        repoRoot: target,
        sourceUrl: url.replace(/\.git$/, ''),
        repoSlug,
        sourceKind: 'github',
        sourceCommit: snapshot.commit,
        sourceRef: snapshot.ref,
        sourceDirty: false,
    };
}
export async function refreshGitCheckout(params) {
    if (params.ref !== undefined)
        validateGitRef(params.ref);
    const cache = await prepareOwnedGitCache({
        target: params.target,
        boundaryRoot: params.boundaryRoot,
        kind: 'repo-source',
        url: params.url,
    });
    const target = cache.target;
    if (cache.isNew) {
        await execFileAsync('git', ['init', '--quiet', target], {
            maxBuffer: 10 * 1024 * 1024,
        });
        await execFileAsync('git', ['remote', 'add', 'origin', params.url], {
            cwd: target,
            maxBuffer: 10 * 1024 * 1024,
        });
    }
    await assertOwnedGitCache({ target, boundaryRoot: params.boundaryRoot, kind: 'repo-source', url: params.url });
    const origin = await gitOutput(target, ['remote', 'get-url', 'origin']);
    if (origin !== params.url) {
        throw new Error(`Git cache origin mismatch for ${target}`);
    }
    let ref;
    let commit;
    if (params.ref !== undefined) {
        await execFileAsync('git', ['fetch', '--depth=1', '--no-tags', 'origin', params.ref], {
            cwd: target,
            maxBuffer: 10 * 1024 * 1024,
        });
        commit = await gitOutput(target, ['rev-parse', '--verify', 'FETCH_HEAD^{commit}']);
        if (!commit)
            throw new Error(`Cannot resolve source ref ${params.ref} for ${params.url}`);
        ref = params.ref;
    }
    else {
        await execFileAsync('git', ['fetch', '--depth=1', '--prune', '--no-tags', 'origin'], {
            cwd: target,
            maxBuffer: 10 * 1024 * 1024,
        });
        await execFileAsync('git', ['remote', 'set-head', 'origin', '--auto'], {
            cwd: target,
            maxBuffer: 10 * 1024 * 1024,
        });
        const symbolicHead = await gitOutput(target, ['symbolic-ref', 'refs/remotes/origin/HEAD']);
        ref = symbolicHead || (await firstExistingRef(target, ['refs/remotes/origin/main', 'refs/remotes/origin/master'])) || '';
        if (!ref)
            throw new Error(`Cannot resolve remote default branch for ${params.url}`);
        commit = await gitOutput(target, ['rev-parse', '--verify', `${ref}^{commit}`]);
        if (!commit)
            throw new Error(`Cannot resolve source commit for ${params.url}`);
    }
    await assertOwnedGitCache({ target, boundaryRoot: params.boundaryRoot, kind: 'repo-source', url: params.url });
    await execFileAsync('git', ['reset', '--hard', commit], { cwd: target });
    await assertOwnedGitCache({ target, boundaryRoot: params.boundaryRoot, kind: 'repo-source', url: params.url });
    await execFileAsync('git', ['clean', '-ffdx'], { cwd: target });
    const checkedOutCommit = await gitOutput(target, ['rev-parse', 'HEAD']);
    if (!checkedOutCommit)
        throw new Error(`Cannot resolve source commit for ${params.url}`);
    return { commit: checkedOutCommit, ref };
}
function validateGitRef(ref) {
    if (!ref ||
        ref.startsWith('-') ||
        /[\x00-\x20\x7f]/.test(ref) ||
        ref.includes('..') ||
        ref.includes('@{') ||
        ref.includes('//') ||
        ref.includes('\\') ||
        /[~^:?*\[\]]/.test(ref) ||
        /[/.]$/.test(ref)) {
        throw new Error(`Unsafe source Git ref: ${ref}`);
    }
}
async function firstExistingRef(cwd, refs) {
    for (const ref of refs) {
        if (await gitOutput(cwd, ['rev-parse', '--verify', ref]))
            return ref;
    }
    return null;
}
async function gitOutput(cwd, args) {
    try {
        const result = await execFileAsync('git', args, { cwd, maxBuffer: 10 * 1024 * 1024 });
        return result.stdout.trim() || null;
    }
    catch {
        return null;
    }
}
export function toGitHubUrl(input) {
    const trimmed = input.trim();
    if (/^https:\/\/github\.com\/[^/]+\/[^/]+/.test(trimmed))
        return trimmed.replace(/\/$/, '');
    if (/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(trimmed))
        return `https://github.com/${trimmed}`;
    throw new Error(`Unsupported repo input: ${input}`);
}
